<script setup lang="ts">
/**
 * Demo: SnVideoPreview — the custom control bar vs the browser's native one.
 *
 * Left: `controls` (default) renders `SnVideoControls` — play/pause, mute,
 * seekable timeline, current / total time and fullscreen, all drawn with
 * `--sn-web-*` tokens, identical in every browser.
 * Right: `nativeControls` renders the UA's own `<video controls>` bar, which
 * is **unstylable** and differs per browser / OS (shape, order, colors,
 * captions & PiP entries). It exists only as an escape hatch.
 */
import { SnVideoPreview } from '@snui/vue-web';

/**
 * 自包含视频源（data URI，Web Platform Tests media/2x2-green.mp4，BSD-3-Clause）。
 * demo 不依赖任何外网视频源。
 */
const videoSrc =
  'data:video/mp4;base64,';
</script>

<template>
  <div class="demo-col">
    <div class="demo-row">
      <!-- 自定义控制条：默认行为 -->
      <figure class="demo-figure">
        <SnVideoPreview
          :src="videoSrc"
          :width="360"
          aspect-ratio="16 / 9"
          title="自定义控制条"
          alt="自定义控制条演示"
        />
        <figcaption class="demo-caption">
          <strong>自定义控制条</strong>
          <span
            >播放 / 暂停、静音、可拖拽进度条、当前 / 总时长、全屏。全部走
            token，跨浏览器一致。</span
          >
        </figcaption>
      </figure>

      <!-- 浏览器原生控制条：不可美化、跨端不一致 -->
      <figure class="demo-figure">
        <SnVideoPreview
          :src="videoSrc"
          :width="360"
          aspect-ratio="16 / 9"
          :controls="false"
          native-controls
          title="浏览器原生控制条"
          alt="浏览器原生控制条演示"
        />
        <figcaption class="demo-caption">
          <strong>浏览器原生控制条（nativeControls）</strong>
          <span>
            由浏览器绘制，<b>无法通过 CSS 美化</b>，Chrome / Safari / Firefox / iOS / Android
            的按钮数量、顺序、颜色与圆角各不相同，还可能带上字幕、画中画等入口。仅作为逃生舱使用。
          </span>
        </figcaption>
      </figure>
    </div>

    <p class="demo-note">
      交互要点：进度条是原生 <code>&lt;input type="range"&gt;</code>，可用键盘方向键 / Home / End
      调节；全屏按钮只在浏览器支持 Fullscreen API
      时出现（不支持则整颗按钮不渲染，而不是变成死按钮）。
    </p>
  </div>
</template>

